/**
 * Client-side full-text search for Chaos theme.
 * Powered by pre-built offline inverted index generated by build_search_index.py.
 * Pure Vanilla JavaScript with zero third-party dependencies.
 *
 * Its own entry point rather than a module of main.js: foot/js.html loads it
 * only when site.Params.search.enable is set.
 */

const HTML_ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' };

function escapeHTML(str) {
  if (!str) return '';
  return String(str).replace(/[&<>'"]/g, ch => HTML_ESCAPES[ch] || ch);
}

function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// The index arrives as two strings rather than an object of arrays -- the
// terms, and one posting list for each in the same order, both joined by
// spaces -- which the browser parses as two values instead of one array per
// term. A posting list is the gaps between ascending doc ids, less one, each
// written least significant digit first in base 32 over the 64 characters
// below; a digit of 32 or more has another after it. It stays text until a
// query asks for the term, and build_search_index.py is the encoder.
const POSTING_DIGITS = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-_';
const DIGIT_VALUES = new Uint8Array(128);
for (let i = 0; i < POSTING_DIGITS.length; i++) {
  DIGIT_VALUES[POSTING_DIGITS.charCodeAt(i)] = i;
}

// A term in both tiers holds its two lists joined by a space, and each list
// counts its gaps from the start again.
function decodePostings(text) {
  const ids = [];
  let prev = -1;
  let gap = 0;
  let shift = 0;
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code === 32) {
      prev = -1;
      continue;
    }
    const digit = DIGIT_VALUES[code];
    gap |= (digit & 31) << shift;
    if (digit & 32) {
      shift += 5;
    } else {
      prev += gap + 1;
      ids.push(prev);
      gap = 0;
      shift = 0;
    }
  }
  return ids;
}

// The terms string is kept as well, a space at each end, so that every term
// in it has one on both sides: looking for part of a term is then one indexOf
// over the string instead of a walk over the Map's keys.
//
// An index built with Traditional Chinese folded into Simplified brings the
// pairs a query may need, as one string of the two characters of each pair in
// turn, every one of them a single UTF-16 unit.
function addPostings({ index, vocab, fold }, data) {
  if (typeof data?.terms !== 'string' || typeof data.postings !== 'string') {
    throw new Error('unsupported index format');
  }
  if (typeof data.fold === 'string') {
    for (let i = 0; i + 1 < data.fold.length; i += 2) {
      fold.set(data.fold[i], data.fold[i + 1]);
    }
  }
  if (!data.terms) return;
  vocab.push(` ${data.terms} `);
  const terms = data.terms.split(' ');
  const lists = data.postings.split(' ');
  for (let i = 0; i < terms.length; i++) {
    const prior = index.get(terms[i]);
    index.set(terms[i], prior === undefined ? lists[i] : `${prior} ${lists[i]}`);
  }
}

// Whether word is one edit from the term at vocab[start, end): a character
// more or fewer, another in its place, or two neighbours swapped. Past what
// the two have in common at the start and at the end, one edit leaves at
// most that much. Compared in place, as this runs for every term there is.
function oneEditApart(vocab, start, end, word) {
  let head = 0;
  const shorter = Math.min(end - start, word.length);
  while (head < shorter && vocab.charCodeAt(start + head) === word.charCodeAt(head)) head++;
  let termEnd = end - start;
  let wordEnd = word.length;
  while (termEnd > head && wordEnd > head
      && vocab.charCodeAt(start + termEnd - 1) === word.charCodeAt(wordEnd - 1)) {
    termEnd--;
    wordEnd--;
  }
  const termLeft = termEnd - head;
  const wordLeft = wordEnd - head;
  if (termLeft + wordLeft === 1 || (termLeft === 1 && wordLeft === 1)) return true;
  return termLeft === 2 && wordLeft === 2
    && vocab.charCodeAt(start + head) === word.charCodeAt(head + 1)
    && vocab.charCodeAt(start + head + 1) === word.charCodeAt(head);
}

// Named rather than a bare module body: the element check below is an early
// return, which a module's top level cannot do.
function initSearch() {
  const dialog = document.getElementById('searchDialog');
  const input = document.getElementById('searchInput');
  const resultsContainer = document.getElementById('searchResults');
  const closeBtn = document.getElementById('searchClose');
  const toggleBtn = document.getElementById('searchToggle');

  if (!dialog || !input || !resultsContainer) {
    return;
  }

  // { docs, index, vocab } once the core index has loaded. index is a Map
  // from a term to its posting lists, still encoded; a Map rather than an
  // object so that a term such as "constructor" finds nothing inherited.
  // vocab is the terms of each tier as one string, for findTerms, and fold
  // maps a Traditional Chinese character to the Simplified one the index has
  // in its place.
  let indexData = null;
  // What a query is matched against in each document, by doc id: its title,
  // summary and tags in lower case and folded. Filled as documents come up.
  let docText = [];
  let coreLoad = null;
  let bodyRequested = false;
  let selectedIndex = -1;
  let currentResults = [];
  let debounceTimer = null;
  const initialHTML = resultsContainer.innerHTML;

  // Localised strings, from the dialog's data-* attributes (see search.html).
  const {
    msgLoading = 'Loading...',
    msgEmpty = 'No matching posts found',
    msgError = 'Failed to load search index',
    msgDeprecated = 'Deprecated'
  } = dialog.dataset;

  async function fetchJSON(url) {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  }

  // Resolves true once the core index is usable. The promise is kept, so
  // opening the dialog again while it loads, or after, starts nothing new; a
  // failure drops it, and the next opening tries again.
  function loadIndex() {
    coreLoad ??= (async () => {
      resultsContainer.innerHTML = `<div class="search-loading">${escapeHTML(msgLoading)}</div>`;
      try {
        const raw = await fetchJSON(dialog.dataset.indexUrl || '/search-index.json');
        if (!Array.isArray(raw.docs)) throw new Error('unsupported index format');
        indexData = { docs: raw.docs, index: new Map(), vocab: [], fold: new Map() };
        docText = [];
        addPostings(indexData, raw);
        resultsContainer.innerHTML = initialHTML;
        return true;
      } catch (err) {
        coreLoad = null;
        resultsContainer.innerHTML = `<div class="search-error">${escapeHTML(msgError)} (${escapeHTML(err.message)})</div>`;
        return false;
      }
    })();
    return coreLoad;
  }

  // The body index is several times the size of the core one and is wanted
  // only for matches in a post's text, so it waits for the core index and
  // then for the browser to be idle. Titles and tags are searchable meanwhile.
  function scheduleBodyLoad() {
    const bodyUrl = dialog.dataset.bodyIndexUrl;
    if (bodyRequested || !bodyUrl) return;
    bodyRequested = true;

    const load = async () => {
      try {
        addPostings(indexData, await fetchJSON(bodyUrl));
        // Folded with the core index's pairs alone.
        docText = [];
        // What is on screen was ranked without the body index.
        if (dialog.open) performSearch(input.value);
      } catch {
        // Search still works on the core index; the next opening tries again.
        bodyRequested = false;
      }
    };

    if (window.requestIdleCallback) {
      window.requestIdleCallback(load, { timeout: 1500 });
    } else {
      setTimeout(load, 150);
    }
  }

  async function openSearch() {
    dialog.showModal();
    input.focus();
    if (!await loadIndex()) return;
    scheduleBodyLoad();
    performSearch(input.value);
  }

  // Every way out -- the close button, a click on the backdrop, Escape --
  // ends in the dialog's close event, so the reset is here once rather than
  // in each of them.
  dialog.addEventListener('close', () => {
    input.value = '';
    resultsContainer.innerHTML = initialHTML;
    selectedIndex = -1;
    currentResults = [];
  });

  toggleBtn?.addEventListener('click', e => {
    e.preventDefault();
    openSearch();
  });

  closeBtn?.addEventListener('click', () => dialog.close());

  // Close on a click on the backdrop. The dialog has no padding and clips its
  // content, so a click whose target is the dialog itself landed outside it.
  dialog.addEventListener('click', e => {
    if (e.target === dialog) dialog.close();
  });

  // Global hotkey '/' to open search (unless typing in input/textarea)
  document.addEventListener('keydown', e => {
    if (e.key === '/' && !dialog.open) {
      const tag = e.target?.tagName || '';
      if (tag !== 'INPUT' && tag !== 'TEXTAREA' && !e.target.isContentEditable) {
        e.preventDefault();
        openSearch();
      }
    } else if (e.key === 'Escape' && dialog.open) {
      // Not left to the dialog: a search input takes the first Escape to
      // clear itself, so the dialog would need a second one to close.
      dialog.close();
    }
  });

  // The index has Simplified characters where a post has Traditional ones, so
  // whatever is compared with its terms is folded the same way. A pair is one
  // UTF-16 unit for another: the result is as long as the text, and a place
  // in one is the same place in the other.
  function foldText(text) {
    const { fold } = indexData;
    if (fold.size === 0) return text;
    let out = '';
    for (let i = 0; i < text.length; i++) {
      out += fold.get(text[i]) ?? text[i];
    }
    return out;
  }

  function matchText(id) {
    return docText[id] ??= (({ title, summary, tags }) => ({
      title: foldText((title || '').toLowerCase()),
      summary: foldText((summary || '').toLowerCase()),
      tags: foldText((tags || []).join(' ').toLowerCase())
    }))(indexData.docs[id]);
  }

  // Latin words, which the index holds whole or not at all: a query word
  // that is not a term can only be the start of one. Anything else is CJK,
  // where it can be any part of one -- see extractTokens.
  const LATIN_WORD = /^[a-z0-9.+#]+$/;

  // The terms that have text in them, or that start with it, up to limit of
  // them: the core tier's first, each tier's in the order of the index.
  function findTerms(text, limit, atStart) {
    const found = new Set();
    const needle = atStart ? ` ${text}` : text;
    for (const vocab of indexData.vocab) {
      let from = 0;
      while (found.size < limit) {
        const at = vocab.indexOf(needle, from);
        if (at === -1) break;
        const start = atStart ? at + 1 : vocab.lastIndexOf(' ', at) + 1;
        // The space that ends this term is also the one before the next.
        from = vocab.indexOf(' ', start);
        found.add(vocab.slice(start, from));
      }
    }
    return found;
  }

  // A word worth correcting: letters and digits, long enough that one edit
  // leaves most of it, and not a number, where one digit off is another
  // number and not a slip.
  const MISSPELLABLE = /^(?=.*[a-z])[a-z0-9]{4,}$/;

  // The terms one edit from word, up to limit of them, in findTerms' order.
  function nearTerms(word, limit) {
    const found = new Set();
    for (const vocab of indexData.vocab) {
      let start = 1;
      while (start < vocab.length && found.size < limit) {
        const end = vocab.indexOf(' ', start);
        if (Math.abs(end - start - word.length) <= 1 && oneEditApart(vocab, start, end, word)) {
          found.add(vocab.slice(start, end));
        }
        start = end + 1;
      }
    }
    return found;
  }

  function startsTerm(word) {
    return indexData.index.has(word) || findTerms(word, 1, true).size > 0;
  }

  function insideTerm(text) {
    return findTerms(text, 1, false).size > 0;
  }

  // Splits a query into index terms. Called only once the index has loaded:
  // there is no word segmenter here, and the index's own terms stand in for
  // its dictionary.
  function extractTokens(query) {
    const q = foldText(query.trim().toLowerCase());
    if (!q) return [];

    const { index } = indexData;
    const tokens = [];
    // 1. Extract alphanumeric tokens. The index never joins words across - or
    //    _, and across . + # only for the few terms that are one (x.509, c++,
    //    .net), so a word with those is kept whole only while it is a term or
    //    the start of one, and is otherwise the words between them: utf-8 is
    //    utf and 8, node.js is node and js.
    for (const word of q.match(/[a-z0-9.+#]+/g) || []) {
      if (!/[.+#]/.test(word) || startsTerm(word)) {
        tokens.push(word);
      } else {
        tokens.push(...word.split(/[.+#]+/));
      }
    }

    // 2. Extract CJK phrases: what is left of the query without its Latin
    //    words. Every run of 2 to 6 characters that is a term becomes a
    //    token, overlapping ones included -- the indexer emits a long word
    //    and the shorter words inside it, so all of them are there to match.
    const cjkChars = q.replace(/[a-z0-9_\-.+#\s]+/g, '');
    if (cjkChars) {
      const len = cjkChars.length;
      const covered = new Set();
      for (let i = 0; i < len; i++) {
        for (let l = Math.min(6, len - i); l >= 2; l--) {
          const sub = cjkChars.slice(i, i + l);
          if (index.has(sub)) {
            tokens.push(sub);
            for (let k = 0; k < l; k++) covered.add(i + k);
          }
        }
      }
      // What no term covers may still be part of one. The indexer keeps a
      // word it has no shorter words for whole, a name above all, so two
      // characters of a three-character name are no term themselves. The
      // longest piece of each uncovered run that is inside a term becomes a
      // token, for performSearch to look up in the terms that hold it.
      for (let i = 0; i < len; i++) {
        if (covered.has(i)) continue;
        let end = i + 1;
        while (end < len && !covered.has(end)) end++;
        for (let l = end - i; l >= 2; l--) {
          const sub = cjkChars.slice(i, i + l);
          if (insideTerm(sub)) {
            tokens.push(sub);
            for (let k = 0; k < l; k++) covered.add(i + k);
            break;
          }
        }
      }
      // A single character only where nothing longer covers it: on its own
      // it matches far too much to help a query that has a real word in it.
      for (let i = 0; i < len; i++) {
        const single = cjkChars.charAt(i);
        if (!covered.has(i) && index.has(single)) {
          tokens.push(single);
        }
      }
    }

    // Deduplicate tokens, dropping any empty one
    return [...new Set(tokens)].filter(Boolean);
  }

  // One pattern for a whole render. Longest token first, so that where two
  // start at the same place the longer is the one marked.
  function highlightPattern(tokens) {
    const sortedTokens = [...tokens].sort((a, b) => b.length - a.length);
    return new RegExp(`(${sortedTokens.map(escapeRegExp).join('|')})`, 'gi');
  }

  // Matches are found in the folded text and marked in the text as written,
  // which has them at the same places. Each piece is escaped afterwards:
  // matching in escaped text finds tokens inside its entities, the amp of
  // &amp;.
  function highlightText(text, pattern) {
    const written = String(text ?? '');
    let html = '';
    let last = 0;
    for (const match of foldText(written).matchAll(pattern)) {
      const end = match.index + match[0].length;
      html += `${escapeHTML(written.slice(last, match.index))}<mark>${escapeHTML(written.slice(match.index, end))}</mark>`;
      last = end;
    }
    return html + escapeHTML(written.slice(last));
  }

  function performSearch(query) {
    if (!indexData || !query.trim()) {
      resultsContainer.innerHTML = initialHTML;
      currentResults = [];
      selectedIndex = -1;
      return;
    }

    const cleanQuery = foldText(query.trim().toLowerCase());
    let tokens = extractTokens(query);
    if (tokens.length === 0) {
      tokens = [cleanQuery];
    }

    const scores = {};
    const docTermHits = {}; // docId -> Set of tokens
    const corrections = [];
    const docs = indexData.docs;
    const index = indexData.index;

    // Smoothed BM25-style IDF: a term in few documents says more about them
    // than one in most. The floor keeps a common term from counting for nothing.
    const idf = (df, floor) => Math.max(floor, Math.log(1 + (docs.length - df + 0.5) / (df + 0.5)));

    // The Set is for the coverage bonus below, which counts the query's
    // tokens a document matched: a prefix reaches one document through
    // several terms, and that is still one token.
    const addHit = (id, weight, token) => {
      scores[id] = (scores[id] || 0) + weight;
      (docTermHits[id] ??= new Set()).add(token);
    };

    for (const token of tokens) {
      if (index.has(token)) {
        const ids = decodePostings(index.get(token));
        const weight = idf(ids.length, 0.6);
        for (const id of ids) addHit(id, weight, token);
      } else if (token.length >= 2) {
        // Not a term, so perhaps part of one: the start of a word still being
        // typed, or in CJK any piece of a word the indexer kept whole. Each
        // term it is part of counts for about a third of an exact match, and
        // the scan stops at 50 of them -- a short prefix starts hundreds, and
        // none of them is what the reader meant yet.
        const partOf = findTerms(token, 50, LATIN_WORD.test(token));
        for (const term of partOf) {
          const ids = decodePostings(index.get(term));
          const weight = 0.35 * idf(ids.length, 0.3);
          for (const id of ids) addHit(id, weight, token);
        }
        // Part of nothing either, so perhaps misspelt: the terms one edit
        // away, at a fifth of an exact match and no more than 8 of them. A
        // guess, made only when the word as typed would find nothing.
        if (partOf.size === 0 && MISSPELLABLE.test(token)) {
          for (const term of nearTerms(token, 8)) {
            const ids = decodePostings(index.get(term));
            const weight = 0.2 * idf(ids.length, 0.3);
            for (const id of ids) addHit(id, weight, token);
            corrections.push(term);
          }
        }
      }
    }

    const numTokens = tokens.length;
    // A token and what it was corrected to stand for each other where a
    // title or a tag is looked at, and both are marked in the results.
    const fieldTokens = [...tokens, ...corrections];

    // Multi-field boosting & Exact Phrase Matching
    for (const idStr of Object.keys(scores)) {
      const id = Number(idStr);
      const doc = docs[id];
      if (!doc) continue;

      const { title: titleLower, summary: summaryLower, tags: tagsLower } = matchText(id);

      // 1. Exact query phrase match (Highest user intent indicator)
      if (cleanQuery.length >= 2) {
        if (titleLower === cleanQuery) {
          scores[id] += 120; // Exact title match
        } else if (titleLower.includes(cleanQuery)) {
          scores[id] += 60;  // Full query appears consecutively in title
        }
        if (tagsLower.includes(cleanQuery)) {
          scores[id] += 45;  // Full query appears in tags (e.g. "Google+", "FreeBSD")
        }
        if (summaryLower.includes(cleanQuery)) {
          scores[id] += 25;  // Full query appears in summary
        }
      }

      // 2. Individual token matches in Title, Tags, Categories
      for (const token of fieldTokens) {
        if (titleLower.includes(token)) {
          scores[id] += 18;
          if (titleLower.startsWith(token)) {
            scores[id] += 6; // Title starts with token
          }
        }
        if (tagsLower.includes(token)) {
          scores[id] += 12;
        }
      }

      // 3. Coordinate matching / Term coverage bonus
      // Ensure articles that match more or all query terms rank significantly higher
      if (numTokens > 1 && docTermHits[id]) {
        const matchedCount = docTermHits[id].size;
        const coverage = matchedCount / numTokens;
        if (matchedCount === numTokens) {
          scores[id] += 35; // All terms matched bonus
        }
        scores[id] *= (0.5 + 0.5 * coverage);
      }

      // 4. Deprecated / Outdated content demotion
      // Demote score so current articles rank first, but still discoverable when searched
      if (doc.deprecated) {
        scores[id] *= 0.25;
      }
    }

    // Rank doc IDs by score descending; if tied, newer post first (smaller doc_id)
    const rankedIds = Object.keys(scores).map(Number);
    rankedIds.sort((a, b) => {
      const diff = scores[b] - scores[a];
      return Math.abs(diff) > 0.001 ? diff : a - b;
    });

    currentResults = rankedIds.slice(0, 25).map(id => docs[id]);

    renderResults(currentResults, fieldTokens);
  }

  function renderResults(results, tokens) {
    if (results.length === 0) {
      resultsContainer.innerHTML = `<div class="search-empty">${escapeHTML(msgEmpty)}</div>`;
      selectedIndex = -1;
      return;
    }

    const pattern = highlightPattern(tokens);
    const items = results.map((doc, idx) => {
      const titleHighlighted = highlightText(doc.title, pattern);
      const summaryHighlighted = doc.summary ? highlightText(doc.summary, pattern) : '';

      const tagsHTML = doc.tags?.length
        ? `<span class="search-item-tags">${
            doc.tags.slice(0, 3).map(t => `<span class="search-tag">${escapeHTML(t)}</span>`).join('')
          }</span>`
        : '';

      const deprecatedBadge = doc.deprecated
        ? ` <span class="search-badge-deprecated">${escapeHTML(msgDeprecated)}</span>`
        : '';

      return `<li class="search-item" role="option" data-idx="${idx}" id="search-opt-${idx}">` +
        `<a href="${escapeHTML(doc.url)}" class="search-item-link">` +
          '<div class="search-item-header">' +
            `<span class="search-item-title">${titleHighlighted}${deprecatedBadge}</span>` +
            `<span class="search-item-date">${escapeHTML(doc.date)}</span>` +
          '</div>' +
          (summaryHighlighted ? `<div class="search-item-summary">${summaryHighlighted}</div>` : '') +
          tagsHTML +
        '</a>' +
      '</li>';
    });

    resultsContainer.innerHTML = `<ul class="search-list" role="listbox">${items.join('')}</ul>`;
    selectedIndex = -1;
  }

  function updateSelection(newIdx) {
    const items = resultsContainer.querySelectorAll('.search-item');
    if (items.length === 0) return;

    if (selectedIndex >= 0 && items[selectedIndex]) {
      items[selectedIndex].classList.remove('is-selected');
      items[selectedIndex].removeAttribute('aria-selected');
    }

    selectedIndex = newIdx;
    if (selectedIndex < 0) selectedIndex = items.length - 1;
    if (selectedIndex >= items.length) selectedIndex = 0;

    const currentItem = items[selectedIndex];
    if (currentItem) {
      currentItem.classList.add('is-selected');
      currentItem.setAttribute('aria-selected', 'true');
      currentItem.scrollIntoView({ block: 'nearest' });
    }
  }

  // Keyboard navigation inside search input
  input.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      updateSelection(selectedIndex + 1);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      updateSelection(selectedIndex - 1);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const target = currentResults[selectedIndex] ?? currentResults[0];
      if (target) {
        window.location.href = target.url;
      }
    }
  });

  // Debounced input search
  input.addEventListener('input', () => {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => performSearch(input.value), 150);
  });
}

initSearch();
